import qrcode from "qrcode-generator";

/**
 * The QR code of a Glowbook address (decision 102), as a square matrix of
 * dark (true) / light (false) modules, without the quiet zone (the drawing
 * adds it). Generated by `qrcode-generator` (MIT, no dependencies; chosen in
 * supabase/README.md decision 102): byte mode, error correction "M", the
 * smallest version that holds the address. Pure: unit-tested.
 */

/** Modules of white kept around the code, as the QR standard asks. */
export const QR_QUIET_ZONE = 4;

export function qrMatrix(text: string): boolean[][] {
  if (!text) throw new Error("nothing to encode");
  const qr = qrcode(0, "M");
  qr.addData(text, "Byte");
  qr.make();
  const n = qr.getModuleCount();
  return Array.from({ length: n }, (_, row) => Array.from({ length: n }, (_, col) => qr.isDark(row, col)));
}

/**
 * The code as one SVG path in module units (one `M x y h1 v1 h-1 z` square per
 * dark module, runs merged), for an on-screen preview drawn crisp at any size.
 */
export function qrPath(matrix: readonly (readonly boolean[])[], offset = 0): string {
  const parts: string[] = [];
  matrix.forEach((row, y) => {
    let x = 0;
    while (x < row.length) {
      if (!row[x]) {
        x += 1;
        continue;
      }
      const start = x;
      while (x < row.length && row[x]) x += 1;
      parts.push(`M${start + offset} ${y + offset}h${x - start}v1h-${x - start}z`);
    }
  });
  return parts.join("");
}
